v(iso_atom_codes_2_06, true(X == [0'o,0'r,0't,0'h]), (atom_codes('North', [0'N| X]))).
v(iso_atom_codes_2_07, false, (atom_codes('soap', [0's, 0'o, 0'p]))).
v(iso_atom_codes_2_08, error(instantiation_error), (atom_codes(_X, _Y))).
v(eddbali_atom_codes_2_09, error(type_error(atom,f(a))), (atom_codes(f(a), _L))).
v(eddbali_atom_codes_2_10, error(type_error(list,0'x)), (atom_codes(_, 0'x))).
v(eddbali_atom_codes_2_11, error(representation_error(character_code)), (atom_codes(_A, [0'i,0's,-1]))).
v(lgt_atom_codes_2_14, error(type_error(integer,a)), (atom_codes(abc, [a,b,c]))).
v(lgt_atom_codes_2_15, true(Codes == []), (atom_codes('', Codes))).
v(lgt_atom_codes_2_16, true(Atom == ''), (atom_codes(Atom, []))).
v(lgt_atom_codes_2_17, true, (atom_codes('', []))).
v(lgt_atom_codes_2_18, true(v(A,B,C) == v(65,66,67)), (atom_codes('ABC', [A,B,C]))).
v(lgt_atom_codes_2_19, true, (atom_codes('ABC', [65,66,67]))).
v(lgt_atom_codes_2_20, false, (atom_codes('ABC', [66| _]))).
v(lgt_atom_codes_2_21, error(type_error(list,[66| 67])), (atom_codes('ABC', [66| 67]))).
v(lgt_atom_codes_2_22, error(type_error(list,[65,66,67| 'D'])), (atom_codes('ABC', [65,66,67| 'D']))).
v(lgt_atom_codes_2_23, error(type_error(integer, 'D')), (atom_codes('ABC', [65,66,67,'D']))).
v(lgt_atom_codes_2_24, true(Tail == []), (atom_codes('ABC', [65,66,67| Tail]))).
v(lgt_atom_codes_2_25, false, (atom_codes(a, [_, _]))).
